    func process(_ image: UIImage, brightness: Double, contrast: Double, sharpness: Double) -> UIImage? {
        guard let cg = image.cgImage else { return nil }

        let w = cg.width
        let h = cg.height
        let count = w * h * 4

        var pixels = [UInt8](repeating: 0, count: count)

        guard let ctx = CGContext(
            data: &pixels,
            width: w,
            height: h,
            bitsPerComponent: 8,
            bytesPerRow: w * 4,
            space: CGColorSpaceCreateDeviceRGB(),
            bitmapInfo: CGImageAlphaInfo.premultipliedFirst.rawValue |
                CGBitmapInfo.byteOrder32Big.rawValue
        ) else {
            return nil
        }

        ctx.draw(cg, in: CGRect(x: 0, y: 0, width: w, height: h))

        let brightnessIndex = Self.brightnessIndex(brightness)
        let contrastIndex = Self.contrastIndex(contrast)

        if let lut = brightnessLUT[brightnessIndex] {
            for i in stride(from: 0, to: count, by: 4) {
                pixels[i + 1] = lut[Int(pixels[i + 1])]
                pixels[i + 2] = lut[Int(pixels[i + 2])]
                pixels[i + 3] = lut[Int(pixels[i + 3])]
            }
        }

        if let lut = contrastLUT[contrastIndex] {
            for i in stride(from: 0, to: count, by: 4) {
                pixels[i + 1] = lut[Int(pixels[i + 1])]
                pixels[i + 2] = lut[Int(pixels[i + 2])]
                pixels[i + 3] = lut[Int(pixels[i + 3])]
            }
        }

        if sharpness != 0 {
            let s = Float(max(-1, min(1, sharpness / 50.0)))
            let original = pixels

            for y in 0..<h {
                let ym = max(0, y - 1)
                let yp = min(h - 1, y + 1)

                for x in 0..<w {
                    let xm = max(0, x - 1)
                    let xp = min(w - 1, x + 1)

                    let p = (y * w + x) * 4
                    let l = (y * w + xm) * 4
                    let r = (y * w + xp) * 4
                    let t = (ym * w + x) * 4
                    let b = (yp * w + x) * 4

                    for c in 1...3 {
                        let value =
                            Float(original[p + c]) * (1 + 4 * s) -
                            s * Float(
                                original[l + c] +
                                original[r + c] +
                                original[t + c] +
                                original[b + c]
                            )

                        pixels[p + c] = UInt8(
                            max(0, min(255, Int(value.rounded())))
                        )
                    }
                }
            }
        }

        guard let outContext = CGContext(
            data: &pixels,
            width: w,
            height: h,
            bitsPerComponent: 8,
            bytesPerRow: w * 4,
            space: CGColorSpaceCreateDeviceRGB(),
            bitmapInfo: CGImageAlphaInfo.premultipliedFirst.rawValue |
                CGBitmapInfo.byteOrder32Big.rawValue
        ),
        let output = outContext.makeImage()
        else {
            return nil
        }

        return UIImage(
            cgImage: output,
            scale: image.scale,
            orientation: image.imageOrientation
        )
    }

    private static func brightnessIndex(_ value: Double) -> Int {
        let v = max(-5.0, min(5.0, value / 10.0))
        return max(-7, min(8, Int(v * 1.5 + 0.5)))
    }

    private static func contrastIndex(_ value: Double) -> Int {
        let v = max(-5.0, min(5.0, value / 10.0))

        if v > 0 {
            return max(-50, min(100, Int(v * 0.5 + 0.5)))
        }

        return Int(v)
    }
}